@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed = [g for g in evaluated if g.passed]
        return len(passed) / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files} (Python: {self.python_files})")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("Gates:")
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"  [{status_icon}] {g.name}: {g.status} ({g.method}) - {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to find fenced code blocks with optional language and optional filename
    # Common patterns:
    # ```python
    # ```path/to/file.py
    # ```python path/to/file.py
    # ```

    blocks = {}
    # Pattern 1: ```lang filename
    # Pattern 2: ```filename
    # Pattern 3: ```lang

    # We'll use a more robust regex to capture the header line and content
    pattern = r"```(?:([a-zA-Z0-9_\-]+)\s+)?([^\n`]+)?\n(.*?)```"

    matches = re.finditer(pattern, text, re.DOTALL)

    for match in matches:
        lang = match.group(1)
        filename = match.group(2)
        content = match.group(3)

        if not filename:
            # If no filename, we can't map it to a path reliably.
            # Some conventions use the language as a hint, but without a path, we skip.
            # Or if the language is python, maybe we can guess? 
            # The spec says "path->content map". Without a path, we can't create a map entry.
            continue

        # Clean up filename
        filename = filename.strip()
        if not filename:
            continue

        # If the filename looks like a language identifier (e.g. "python"), ignore it as a filename
        # unless it has a slash or dot.
        if '/' not in filename and '.' not in filename:
            # It might be just a language tag on the second line? 
            # Actually, standard markdown is ```lang\ncontent\n```
            # If the header was just "python", group 2 is None.
            # If the header was "python file.py", group 1 is python, group 2 is file.py.
            # If the header was "file.py", group 1 is None, group 2 is file.py.
            pass

        # If filename is just a language tag, skip
        if filename.lower() in ('python', 'py', 'text', 'json', 'yaml', 'toml'):
            continue

        # Sanitize path if needed? The spec says extract_code_blocks recovers path->content.
        # It doesn't explicitly say to sanitize, but artifacts.py does.
        # We'll return raw paths here, and let the harness filter/sanitize later if needed.
        # However, if the path is malformed, it might be better to sanitize it now?
        # The spec for extract_code_blocks says "Recovers a path->content map".
        # Let's assume the paths are as written.

        blocks[filename] = content

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed files
        authored_bundle = filter_bundle(bundle)

        # Create temp dir
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            # Verify directory
            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Filter out excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]
                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        full_path = os.path.join(root, file)
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                authored[rel_path] = f.read()
                        except Exception:
                            pass

        python_files = [p for p in authored if p.endswith('.py')]
        authored_files_count = len(authored)
        python_files_count = len(python_files)

        gates = []

        # Gate 1: Syntax
        gates.append(self._gate_syntax(workdir, python_files))

        # Gate 2: Build
        gates.append(self._gate_build(workdir, authored))

        # Gate 3: Smoke
        gates.append(self._gate_smoke(workdir, authored))

        # Gate 4: Tests
        gates.append(self._gate_tests(workdir, authored))

        # Gate 5: Telemetry
        gates.append(self._gate_telemetry(workdir, python_files))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files_count,
            python_files=python_files_count,
            source=source
        )

    def _gate_syntax(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()
        if not python_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='No Python files found',
                duration_s=time.time() - start
            )

        errors = []
        for rel_path in python_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    code = f.read()
                ast.parse(code)
            except SyntaxError as e:
                errors.append(f"{rel_path}: {e}")
            except Exception as e:
                errors.append(f"{rel_path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast.parse',
                detail='; '.join(errors),
                duration_s=duration
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast.parse',
            detail=f"All {len(python_files)} Python files parsed successfully",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No packaging metadata found (pyproject.toml, setup.py, or setup.cfg)',
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(key in data for key in ('project', 'build-system', 'tool')):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='tomllib',
                        detail='pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool])',
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='tomllib',
                    detail=f'pyproject.toml is invalid: {e}',
                    duration_s=time.time() - start
                )

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, '-m', 'pip', '--version'], 
                           capture_output=True, timeout=10, check=True)

            # Run pip install -e . --no-deps --no-build-isolation
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip_install',
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr}',
                    duration_s=duration
                )
        except FileNotFoundError:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available',
                duration_s=time.time() - start
            )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out',
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'pip install error: {e}',
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Find non-test authored modules
        # "Non-test authored modules" -> .py files that are not test files
        # Test files are identified by "test" in basename.lower()
        modules = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            modules.append(path)

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No importable non-test modules found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        env = os.environ.copy()
        current_path = env.get('PYTHONPATH', '')
        new_path = f"{workdir}{os.pathsep}{src_dir}"
        if current_path:
            new_path = f"{new_path}{os.pathsep}{current_path}"
        env['PYTHONPATH'] = new_path

        # Try importing each module in a subprocess
        # We'll try to import them one by one or all together?
        # Spec: "Non-test authored modules must import in a subprocess"
        # If any fails with syntax/runtime error -> FAILED
        # If fails solely with ModuleNotFoundError for uninstalled third-party -> SKIPPED

        # Let's try to import all modules in one subprocess to save time, 
        # but we need to distinguish errors.
        # Better: Try to import each module individually? 
        # Or write a script that tries to import all and reports errors.

        script = []
        script.append("import sys")
        script.append("import importlib")
        script.append("errors = []")
        script.append("skipped = False")

        for mod_path in modules:
            # Convert path to module name
            # e.g. src/foo/bar.py -> foo.bar
            # e.g. foo/bar.py -> foo.bar
            rel_path = mod_path
            if rel_path.startswith('src/'):
                rel_path = rel_path[4:]
            if rel_path.endswith('.py'):
                rel_path = rel_path[:-3]
            parts = rel_path.split('/')
            module_name = '.'.join(parts)

            script.append("try:")
            script.append(f"    importlib.import_module('{module_name}')")
            script.append("except ModuleNotFoundError as e:")
            script.append("    if 'opentelemetry' in str(e) or 'no module named' in str(e).lower():")
            script.append("        skipped = True")
            script.append("    else:")
            script.append(f"        errors.append('{module_name}: ' + str(e))")
            script.append("except Exception as e:")
            script.append(f"    errors.append('{module_name}: ' + str(e))")

        script.append("if errors:")
        script.append("    print('ERRORS:' + ';'.join(errors))")
        script.append("elif skipped:")
        script.append("    print('SKIPPED')")
        script.append("else:")
        script.append("    print('OK')")

        try:
            result = subprocess.run(
                [self.python_executable, '-c', '\n'.join(script)],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            output = result.stdout.strip()

            if output == 'OK':
                return GateResult(
                    name='smoke',
                    status=PASSED,
                    method='import_check',
                    detail='All modules imported successfully',
                    duration_s=duration
                )
            elif output == 'SKIPPED':
                return GateResult(
                    name='smoke',
                    status=SKIPPED,
                    method='import_check',
                    detail='Modules skipped due to missing third-party dependencies',
                    duration_s=duration
                )
            elif output.startswith('ERRORS:'):
                error_msg = output[7:]
                return GateResult(
                    name='smoke',
                    status=FAILED,
                    method='import_check',
                    detail=error_msg,
                    duration_s=duration
                )
            else:
                # Unexpected output or crash
                return GateResult(
                    name='smoke',
                    status=FAILED,
                    method='import_check',
                    detail=f'Unexpected import result: {output} | Stderr: {result.stderr}',
                    duration_s=duration
                )

        except Exception as e:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail=f'Import check failed: {e}',
                duration_s=time.time() - start
            )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start = time.time()

        # Discover test files
        test_files = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                test_files.append(path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest',
                detail='No test files found',
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        env = os.environ.copy()
        current_path = env.get('PYTHONPATH', '')
        new_path = f"{workdir}{os.pathsep}{src_dir}"
        if current_path:
            new_path = f"{new_path}{os.pathsep}{current_path}"
        env['PYTHONPATH'] = new_path

        # Check if pytest is installed
        try:
            subprocess.run([self.python_executable, '-m', 'pytest', '--version'], 
                           capture_output=True, timeout=10, check=True)
            use_pytest = True
        except Exception:
            use_pytest = False

        if use_pytest:
            # Run pytest
            try:
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start
                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest',
                        detail='All tests passed',
                        duration_s=duration
                    )
                else:
                    # Check if it was skipped due to ModuleNotFoundError
                    if 'ModuleNotFoundError' in result.stderr or 'ModuleNotFoundError' in result.stdout:
                        # Check if it's specifically about uninstalled third-party packages
                        # This is tricky. If pytest fails to collect because of import errors,
                        # it might report errors.
                        # Spec: "If 0 tests are collected because of ModuleNotFoundError for an uninstalled third-party package, return SKIPPED"
                        # If tests ran and failed, it's FAILED.
                        # If collection failed due to ModuleNotFoundError, it's SKIPPED.
                        # Pytest usually reports "errors" during collection.
                        if "error" in result.stdout.lower() and "ModuleNotFoundError" in result.stdout:
                             # Heuristic: if no tests passed and errors are import related
                             if "passed" not in result.stdout or "0 passed" in result.stdout:
                                 return GateResult(
                                    name='tests',
                                    status=SKIPPED,
                                    method='pytest',
                                    detail='Tests skipped due to missing dependencies',
                                    duration_s=duration
                                 )

                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='pytest',
                        detail=f'Tests failed: {result.stdout[-500:]}',
                        duration_s=duration
                    )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='pytest',
                    detail=f'Pytest execution error: {e}',
                    duration_s=time.time() - start
                )
        else:
            # Stdlib fallback
            # Run a subprocess that imports each test file and collects/executes 
            # bare def test_*() functions AND unittest.TestCase subclasses

            script = []
            script.append("import sys")
            script.append("import unittest")
            script.append("import importlib")
            script.append("import traceback")
            script.append("import os")

            # Add workdir and src to path
            script.append(f"sys.path.insert(0, r'{workdir}')")
            script.append(f"sys.path.insert(0, r'{src_dir}')")

            script.append("test_files = []")
            for tf in test_files:
                # Convert to module name
                rel_path = tf
                if rel_path.startswith('src/'):
