                if rel_path.endswith('.py'):
                    rel_path = rel_path[:-3]
                parts = rel_path.split('/')
                module_name = '.'.join(parts)
                script.append(f"test_files.append('{module_name}')")

            script.append("collected_tests = 0")
            script.append("failed_tests = 0")
            script.append("skipped_due_to_import = False")
            script.append("errors = []")

            script.append("for mod_name in test_files:")
            script.append("    try:")
            script.append("        mod = importlib.import_module(mod_name)")
            script.append("        # Collect bare test functions")
            script.append("        for name in dir(mod):")
            script.append("            if name.startswith('test_'):")
            script.append("                func = getattr(mod, name)")
            script.append("                if callable(func) and func.__module__ == mod_name:")
            script.append("                    # Check if it takes 0 required args")
            script.append("                    import inspect")
            script.append("                    sig = inspect.signature(func)")
            script.append("                    params = sig.parameters")
            script.append("                    required_args = [p for p in params.values() if p.default == inspect.Parameter.empty and p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD, inspect.Parameter.KEYWORD_ONLY)]")
            script.append("                    if len(required_args) == 0:")
            script.append("                        collected_tests += 1")
            script.append("                        try:")
            script.append("                            func()")
            script.append("                        except Exception as e:")
            script.append("                            failed_tests += 1")
            script.append("                            errors.append(f'{mod_name}.{name}: {e}')")
            script.append("        # Collect unittest.TestCase subclasses")
            script.append("        for name in dir(mod):")
            script.append("            cls = getattr(mod, name)")
            script.append("            if isinstance(cls, type) and issubclass(cls, unittest.TestCase) and cls.__module__ == mod_name:")
            script.append("                suite = unittest.TestLoader().loadTestsFromTestCase(cls)")
            script.append("                for test in suite:")
            script.append("                    collected_tests += 1")
            script.append("                    try:")
            script.append("                        test.run()")
            script.append("                    except Exception as e:")
