            script.append("                        errors.append(f'{mod_name}.{name}: {e}')")
            script.append("    except ModuleNotFoundError as e:")
            script.append("        if 'opentelemetry' in str(e) or 'no module named' in str(e).lower():")
            script.append("            skipped_due_to_import = True")
            script.append("        else:")
            script.append("            errors.append(f'{mod_name}: {e}')")
            script.append("    except Exception as e:")
            script.append("        errors.append(f'{mod_name}: {e}')")

            script.append("if collected_tests == 0 and skipped_due_to_import:")
            script.append("    print('SKIPPED')")
            script.append("elif collected_tests == 0:")
            script.append("    print('FAILED: No tests collected')")
            script.append("elif failed_tests > 0:")
            script.append("    print('FAILED: ' + ';'.join(errors))")
            script.append("else:")
            script.append("    print('PASSED')")

            try:
