                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                duration = time.time() - start
                output = result.stdout.strip()

                if output == 'PASSED':
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='stdlib_fallback',
                        detail='All tests passed',
                        duration_s=duration
                    )
                elif output == 'SKIPPED':
                    return GateResult(
