                        status=FAILED,
                        method='stdlib_fallback',
                        detail=output,
                        duration_s=duration
                    )
                else:
                    return GateResult(
                        name='tests',
                        status=FAILED,
                        method='stdlib_fallback',
                        detail=f'Unexpected test result: {output} | Stderr: {result.stderr}',
                        duration_s=duration
                    )
            except Exception as e:
                return GateResult(
                    name='tests',
                    status=FAILED,
                    method='stdlib_fallback',
                    detail=f'Test execution error: {e}',
                    duration_s=time.time() - start
                )

    def _gate_telemetry(self, workdir: str, python_files: List[str]) -> GateResult:
        start = time.time()

        if not python_files:
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='No Python files to analyze',
                duration_s=time.time() - start
            )

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 
            'start_span', 
            'get_tracer', 
            'get_tracer_provider', 
            'set_tracer_provider', 
            'get_meter'
        }

        for rel_path in python_files:
            full_path = os.path.join(workdir, rel_path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    code = f.read()
                tree = ast.parse(code)

                for node in ast.walk(tree):
                    # Check for import opentelemetry or from opentelemetry ... import ...
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                                has_import = True
                    elif isinstance(node, ast.ImportFrom):
                        if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                            has_import = True

                    # Check for calls to tracer/span methods
                    if isinstance(node, ast.Call):
                        func = node.func
                        # Handle method calls like tracer.start_span()
                        if isinstance(func, ast.Attribute):
                            if func.attr in tracer_methods:
                                has_call = True
                        # Handle function calls like get_tracer()
                        elif isinstance(func, ast.Name):
                            if func.id in tracer_methods:
                                has_call = True

            except Exception:
                continue

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(
                name='telemetry',
                status=PASSED,
                method='ast_analysis',
                detail='OpenTelemetry import and tracer/span calls found',
                duration_s=duration
            )
        else:
            detail = []
            if not has_import:
                detail.append('No OpenTelemetry import found')
            if not has_call:
                detail.append('No tracer/span method calls found')
            return GateResult(
                name='telemetry',
                status=FAILED,
                method='ast_analysis',
                detail='; '.join(detail),
                duration_s=duration
            )

